package server
import "net/http"
const indexHTML=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BotWeb</title><link rel="stylesheet" href="/app.css"></head><body><header><a class="brand" href="/"><strong>BotWeb</strong><span>PBMP fleet console</span></a><button id="refresh" type="button">Refresh</button></header><main id="app"><p id="notice" role="status">Loading…</p></main><script src="/app.js"></script></body></html>`
const css=`:root{font-family:system-ui,sans-serif;color-scheme:dark;background:#101318;color:#edf1f7}*{box-sizing:border-box}body{margin:0}a{color:inherit}.brand{text-decoration:none}header{display:flex;justify-content:space-between;align-items:center;padding:1.1rem 5vw;border-bottom:1px solid #2a3039}header strong{font-size:1.4rem}header span{margin-left:.8rem;color:#9da8b7}button,.action{padding:.55rem .9rem;border:1px solid #4b5666;border-radius:.45rem;background:#202630;color:inherit;text-decoration:none;display:inline-block}main{max-width:1100px;margin:auto;padding:2rem 5vw}.summary{display:flex;gap:1rem;margin-bottom:1.5rem}.summary div,.card,.panel{background:#171c23;border:1px solid #2b333e;border-radius:.65rem}.summary div{padding:1rem 1.4rem;min-width:8rem}.summary b{display:block;font-size:1.6rem}.summary span,.muted{color:#9da8b7}.fleet{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:1rem}.card,.panel{padding:1.1rem}.cardlink{text-decoration:none;display:block}.cardlink:hover .card{border-color:#536175}.top{display:flex;justify-content:space-between;gap:1rem}.state{font-size:.8rem;text-transform:uppercase;letter-spacing:.05em}.online{color:#86d993}.offline{color:#e59a9a}.caps,.actions{display:flex;flex-wrap:wrap;gap:.4rem}.cap{font-size:.75rem;border:1px solid #394351;border-radius:1rem;padding:.2rem .5rem}.network{display:flex;justify-content:space-between;padding:.45rem 0;border-top:1px solid #252c35}.detailgrid{display:grid;grid-template-columns:2fr 1fr;gap:1rem}.back{display:inline-block;margin-bottom:1rem;color:#aeb9c8}.error{color:#e59a9a}h2{margin:.1rem 0}@media(max-width:700px){header span{display:none}.summary{overflow:auto}.detailgrid{grid-template-columns:1fr}}`
const js=`const app=document.querySelector('#app'),refresh=document.querySelector('#refresh');async function get(u){const r=await fetch(u,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}async function post(u,v){const r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(v)});if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}function esc(s){const d=document.createElement('div');d.textContent=String(s??'');return d.innerHTML}function capsHTML(c){return(c||[]).map(x=>'<span class="cap">'+esc(x)+'</span>').join('')}function netsHTML(n){return(n||[]).map(x=>'<div class="network"><span>'+esc(x.name)+'</span><span class="muted">'+esc(x.state)+'</span></div>').join('')||'<p class="muted">None reported</p>'}async function botData(b){try{const[info,caps,nets,protocol]=await Promise.all([get('/api/v1/bots/'+encodeURIComponent(b.id)+'/info'),get('/api/v1/bots/'+encodeURIComponent(b.id)+'/capabilities'),get('/api/v1/bots/'+encodeURIComponent(b.id)+'/networks'),get('/api/v1/bots/'+encodeURIComponent(b.id)+'/protocol')]);return{b,info,caps:caps.capabilities||[],nets:nets.networks||[],protocol,reachable:true}}catch(e){return{b,reachable:false}}}async function fleet(){app.innerHTML='<p>Loading fleet…</p>';try{const bots=await get('/api/v1/bots'),data=await Promise.all(bots.map(botData)),online=data.filter(x=>x.reachable&&x.info.state==='online').length;app.innerHTML='<section class="summary"><div><b>'+bots.length+'</b><span>registered</span></div><div><b>'+online+'</b><span>online</span></div><div><b>'+(bots.length-online)+'</b><span>offline</span></div></section><section class="fleet">'+data.map(x=>{if(!x.reachable)return'<a class="cardlink" href="/bots/'+encodeURIComponent(x.b.id)+'"><article class="card"><div class="top"><h2>'+esc(x.b.name)+'</h2><span class="state offline">unreachable</span></div><p class="muted">'+esc(x.b.id)+'</p></article></a>';const on=x.info.state==='online';return'<a class="cardlink" href="/bots/'+encodeURIComponent(x.b.id)+'"><article class="card"><div class="top"><div><h2>'+esc(x.b.name)+'</h2><span class="muted">'+esc(x.info.implementation)+' '+esc(x.info.version)+'</span></div><span class="state '+(on?'online':'offline')+'">'+esc(x.info.state)+'</span></div><p class="muted">'+esc(x.b.id)+'</p><h3>Networks</h3>'+netsHTML(x.nets)+'</article></a>'}).join('')+'</section>'}catch(e){app.innerHTML='<p class="error">Unable to load registry.</p>'}}function actions(c,id){const known=[['channels.list','Channels'],['modules.list','Modules'],['scripts.list','Scripts'],['logs.stream','Logs'],['metrics.read','Metrics'],['config.read','Configuration']];return known.filter(x=>c.includes(x[0])).map(x=>x[0]==='channels.list'?'<a class="action" href="/bots/'+encodeURIComponent(id)+'/channels">Channels</a>':x[0]==='modules.list'?'<a class="action" href="/bots/'+encodeURIComponent(id)+'/modules">Modules</a>':'<span class="action" title="Advertised by '+esc(id)+'">'+x[1]+'</span>').join('')||'<span class="muted">No optional management capabilities advertised.</span>'}async function channels(id){app.innerHTML='<p>Loading channels…</p>';try{const bots=await get('/api/v1/bots'),b=bots.find(x=>x.id===id);if(!b)throw new Error('not found');const caps=await get('/api/v1/bots/'+encodeURIComponent(id)+'/capabilities');if(!(caps.capabilities||[]).includes('channels.list')){app.innerHTML='<a class="back" href="/bots/'+encodeURIComponent(id)+'">← Bot</a><p class="error">This bot does not advertise channels.list.</p>';return}const data=await get('/api/v1/bots/'+encodeURIComponent(id)+'/channels'),cv=caps.capabilities||[],canJoin=cv.includes('channels.join'),canPart=cv.includes('channels.part');app.innerHTML='<a class="back" href="/bots/'+encodeURIComponent(id)+'">← '+esc(b.name)+'</a><h1>Channels</h1>'+(canJoin?'<form id="joinform" class="panel"><label>Join channel <input name="name" required placeholder="#channel"></label><label> Network <input name="network" required value="'+esc((data.channels[0]||{}).network||'')+'"></label><button>Join</button></form>':'')+'<div class="panel">'+(data.channels||[]).map(c=>'<div class="network"><span><strong>'+esc(c.name)+'</strong><br><small class="muted">'+esc(c.network)+'</small></span><span><span class="muted">'+esc(c.state)+'</span> '+(canPart?'<button class="part" data-network="'+esc(c.network)+'" data-name="'+esc(c.name)+'">Part</button>':'')+'</span></div>').join('')+'</div>';const jf=document.querySelector('#joinform');if(jf)jf.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(jf);try{await post('/api/v1/bots/'+encodeURIComponent(id)+'/channels/join',{network:f.get('network'),name:f.get('name')});channels(id)}catch(e){alert('Join failed')}});document.querySelectorAll('.part').forEach(x=>x.addEventListener('click',async()=>{try{await post('/api/v1/bots/'+encodeURIComponent(id)+'/channels/part',{network:x.dataset.network,name:x.dataset.name});channels(id)}catch(e){alert('Part failed')}}))}catch(e){app.innerHTML='<a class="back" href="/">← Fleet</a><p class="error">Unable to load channels.</p>'}}async function modules(id){app.innerHTML='<p>Loading modules…</p>';try{const bots=await get('/api/v1/bots'),b=bots.find(x=>x.id===id);if(!b)throw new Error('not found');const caps=await get('/api/v1/bots/'+encodeURIComponent(id)+'/capabilities');if(!(caps.capabilities||[]).includes('modules.list')){app.innerHTML='<a class="back" href="/bots/'+encodeURIComponent(id)+'">← Bot</a><p class="error">This bot does not advertise modules.list.</p>';return}const data=await get('/api/v1/bots/'+encodeURIComponent(id)+'/modules');app.innerHTML='<a class="back" href="/bots/'+encodeURIComponent(id)+'">← '+esc(b.name)+'</a><h1>Modules</h1><div class="panel">'+(data.modules||[]).map(m=>'<div class="network"><span><strong>'+esc(m.id)+'</strong><br><small class="muted">'+esc(m.runtime)+'</small></span><span><span class="muted">'+esc(m.state)+'</span><br><small>'+capsHTML(m.capabilities||[])+'</small></span></div>').join('')+'</div>'}catch(e){app.innerHTML='<a class="back" href="/">← Fleet</a><p class="error">Unable to load modules.</p>'}}async function detail(id){app.innerHTML='<p>Loading bot…</p>';try{const bots=await get('/api/v1/bots'),b=bots.find(x=>x.id===id);if(!b)throw new Error('not found');const x=await botData(b);if(!x.reachable){app.innerHTML='<a class="back" href="/">← Fleet</a><div class="panel"><h2>'+esc(b.name)+'</h2><p class="error">PBMP unavailable</p></div>';return}const on=x.info.state==='online';app.innerHTML='<a class="back" href="/">← Fleet</a><div class="top"><div><h1>'+esc(b.name)+'</h1><p class="muted">'+esc(x.info.implementation)+' '+esc(x.info.version)+' · PBMP '+esc(x.protocol.protocol||'1')+'</p></div><span class="state '+(on?'online':'offline')+'">'+esc(x.info.state)+'</span></div><section class="detailgrid"><div class="panel"><h2>Networks</h2>'+netsHTML(x.nets)+'<h2>Available management</h2><div class="actions">'+actions(x.caps,b.id)+'</div></div><aside class="panel"><h2>Capabilities</h2><div class="caps">'+capsHTML(x.caps)+'</div></aside></section>'}catch(e){app.innerHTML='<a class="back" href="/">← Fleet</a><p class="error">Bot not found or unavailable.</p>'}}function load(){const m=location.pathname.match(/^\\/bots\\/([^/]+)\\/?$/);m?detail(decodeURIComponent(m[1])):fleet()}refresh.addEventListener('click',load);load();`
func assetCSS(w http.ResponseWriter,_ *http.Request){w.Header().Set("Content-Type","text/css; charset=utf-8");w.Write([]byte(css))}
func assetJS(w http.ResponseWriter,_ *http.Request){w.Header().Set("Content-Type","application/javascript; charset=utf-8");w.Write([]byte(js))}
